('plateau-qinghai','青藏高原','plateau',91.0,33.3,'中国西南部','世界屋脊','青藏高原平均海拔很高，雪山与冰川广布。长江、黄河等大河从这里出发，向远方流去。','把它想成中国西南部的一张高高的桌子：高原很高，河流从这里出发。','哪一座高原常被称为“世界屋脊”？','青藏高原',['黄土高原','内蒙古高原','云贵高原'],['西南高地','大河源区']),
('river-yangtze','长江','river',111.2,30.9,'从青藏高原流向东海','中国最长的河流','长江发源于青藏高原，总体向东流入东海。沿着它旅行，可以从高山峡谷来到平原，再看到大海。','长江长，向东忙；穿过山峡，汇入东海。','长江最终注入哪个海？','东海',['渤海','南海','北冰洋'],['发源于青藏高原','注入东海']),
('lake-poyang','鄱阳湖','lake',116.25,29.1,'江西省北部','中国最大的淡水湖','鄱阳湖位于江西省北部，与长江相连。湖面会随季节水位变化，它也是很多候鸟重要的栖息地。','鄱阳在江西，候鸟来休息；记住它是淡水湖。','鄱阳湖位于哪个省？','江西省',['江苏省','浙江省','湖南省'],['淡水湖','候鸟栖息地']),
('mountain-himalaya','喜马拉雅山脉','mountain',87.0,28.7,'青藏高原南缘','世界最高的山脉','喜马拉雅山脉像一道高大的墙，绵延在青藏高原南缘。珠穆朗玛峰就在这条山脉中。','高原南边一堵墙，珠峰站在喜马拉雅山上。','珠穆朗玛峰属于哪条山脉？','喜马拉雅山脉',['天山山脉','秦岭','太行山脉'],['青藏高原南缘','珠穆朗玛峰']),
('basin-tarim','塔里木盆地','basin',83.2,39.0,'新疆南部','中国最大的盆地','塔里木盆地位于天山以南、昆仑山以北。盆地中有广阔的塔克拉玛干沙漠，周围山麓分布着绿洲。','天山南，昆仑北；沙漠中间，绿洲围一圈。','塔里木盆地位于天山的哪一侧？','南侧',['北侧','东侧','西侧'],['新疆南部','沙漠与绿洲']),
('river-yellow','黄河','river',110.4,36.2,'青藏高原至渤海','认识大大的“几”字弯','黄河发源于青藏高原，流经黄土高原，携带泥沙向东流入渤海。在地图上，它的中上游弯出了醒目的“几”字形。','黄河画个“几”，最后到渤海；沿着弯弯的河道找方向。','黄河最终注入哪个海？','渤海',['东海','南海','地中海'],['“几”字形河道','注入渤海']),
('plain-northeast','东北平原','plain',124.0,45.0,'中国东北部','中国最大的平原','东北平原地势比较平坦，由松嫩平原、三江平原、辽河平原等组成。这里有肥沃的黑土，是重要的粮食产区。','东北平原黑土香，平平展展种粮忙。','哪一处是中国最大的平原？','东北平原',['华北平原','长江中下游平原','四川盆地'],['东北地区','黑土与粮食']),
('lake-qinghai','青海湖','lake',100.2,36.85,'青海省东北部','中国最大的湖泊','青海湖位于青海省，是中国最大的湖泊，也是咸水湖。它在青藏高原东北部，湖水与草原、远山相伴。','青海省里青海湖，名字相同不迷糊；湖水带盐，是咸水湖。','青海湖属于哪一种湖泊？','咸水湖',['淡水湖','火山口中的熔岩湖','人工游泳池'],['咸水湖','青藏高原东北部']),
('mountain-kunlun','昆仑山脉','mountain',86.0,36.2,'青藏高原北部边缘','高原北侧的山脊','昆仑山脉大体呈东西走向，位于青藏高原北部边缘。它的北边可以找到塔里木盆地。','昆仑像高原北边的长围墙，北面邻着塔里木盆地。','昆仑山脉北侧的重要盆地是？','塔里木盆地',['四川盆地','准噶尔盆地','吐鲁番盆地'],['东西走向','高原北缘']),
('mountain-tianshan','天山山脉','mountain',85.3,43.0,'新疆中部','新疆中间的一条山脉','天山横贯新疆中部。它的北侧是准噶尔盆地，南侧是塔里木盆地，像把新疆分成南北两部分的脊梁。','天山在中间，准噶尔在北，塔里木在南。','天山北侧是哪个盆地？','准噶尔盆地',['塔里木盆地','四川盆地','柴达木盆地'],['新疆中部','南北分界']),
('mountain-qilian','祁连山脉','mountain',99.2,38.5,'甘肃与青海交界一带','河西走廊南侧的雪山','祁连山位于青藏高原东北部边缘，山地融雪为周边地区提供水源。它的北侧可以找到河西走廊。','河西走廊南边看，祁连雪山一长串。','河西走廊南侧的山脉是？','祁连山脉',['武夷山脉','太行山脉','大兴安岭'],['青藏高原东北缘','河西走廊南侧']),
('mountain-qinling','秦岭','mountain',108.5,33.7,'中国中部，陕西南部一带','认识中国南北差异','秦岭大体呈东西走向。秦岭—淮河一线是认识中国南北方自然差异的一条重要地理界线。','秦岭牵着淮河走，南北差异记心头。','哪条山脉常与淮河一起作为南北方的重要地理界线？','秦岭',['昆仑山脉','天山山脉','武夷山脉'],['东西走向','秦岭—淮河一线']),
('mountain-daxingan','大兴安岭','mountain',122.0,48.0,'内蒙古高原与东北平原之间','草原与平原之间的山岭','大兴安岭位于内蒙古高原与东北平原之间，大体呈东北—西南走向。东边是较低的平原，西边是高原。','大兴安岭站中间，西边高原、东边平原。','大兴安岭东侧主要是哪片平原？','东北平原',['华北平原','长江中下游平原','成都平原'],['东北—西南走向','阶梯分界山脉']),
('mountain-taihang','太行山脉','mountain',113.8,37.5,'黄土高原与华北平原之间','高原与平原的台阶边','太行山大体呈东北—西南走向，东侧是华北平原，西侧连接黄土高原。山西、山东的名称也可以帮助记忆方位。','太行东边平，西边高；从高原走下大台阶。','太行山脉东侧是哪片平原？','华北平原',['东北平原','长江中下游平原','松嫩平原'],['华北地区','东侧为华北平原']),
('mountain-wushan','巫山','mountain',109.8,31.0,'重庆与湖北交界一带','长江穿过的山地','巫山位于四川盆地东缘一带。长江在这一带穿越山地，形成壮丽的三峡景观。','长江向东穿山走，巫山附近看峡谷。','长江三峡附近可以找到哪座山脉？','巫山',['天山山脉','大兴安岭','武夷山脉'],['四川盆地东缘','长江三峡']),
('mountain-hengduan','横断山脉','mountain',99.1,28.0,'青藏高原东南缘','山高谷深，河流相间','横断山脉位于青藏高原东南缘，许多山岭与河谷大体南北排列。高山和深谷交错，地形十分起伏。','横断山，山连山；南北山谷，河流穿。','横断山脉的典型地形是什么？','山高谷深',['一望无际的平原','低平的海滩','没有起伏的沙地'],['南北排列','青藏高原东南缘']),
('mountain-wuyi','武夷山脉','mountain',117.2,27.5,'福建与江西交界一带','东南地区的绿色山脉','武夷山脉大体呈东北—西南走向，位于福建与江西交界一带。这里山林茂密，也是东南地区重要的分水岭。','福建江西手牵手，中间武夷山林秀。','武夷山脉主要位于哪两个省的交界一带？','福建与江西',['青海与西藏','吉林与黑龙江','山东与河南'],['东南地区','闽赣交界']),
('river-pearl','珠江','river',112.3,23.1,'中国南部','流向南海的水系','珠江是中国南部重要的水系，主要由西江、北江和东江组成。它们汇集后，经珠江三角洲流入南海。','西北东，来相逢；珠江入海，面向南。','珠江水系最终流入哪个海？','南海',['渤海','东海','北冰洋'],['西江、北江、东江','注入南海']),
('river-heilong','黑龙江','river',129.0,49.0,'中国东北部','东北边境的大河','黑龙江位于中国东北部，是中国与俄罗斯之间的重要界河之一。它向东流去，松花江是它的重要支流。','东北找黑龙江，松花江水来汇上。','松花江是哪条大河的支流？','黑龙江',['长江','黄河','珠江'],['东北地区','界河']),
('river-songhua','松花江','river',126.8,45.8,'吉林与黑龙江一带','东北平原上的大河','松花江流经吉林、黑龙江等地，沿途经过东北平原。它汇入黑龙江，是东北地区重要的河流。','松花江在东北转，最后汇入黑龙江。','松花江最终汇入哪条河？','黑龙江',['黄河','塔里木河','长江'],['东北地区','黑龙江支流']),
('river-yarlung','雅鲁藏布江','river',91.5,29.2,'西藏南部','在高原上拐大弯的河','雅鲁藏布江主要流经西藏南部，沿喜马拉雅山脉北侧向东流，之后转向南。它流经著名的雅鲁藏布大峡谷。','藏南大河向东走，遇见大峡谷，再把方向扭。','雅鲁藏布江主要流经哪个自治区？','西藏自治区',['新疆维吾尔自治区','宁夏回族自治区','广西壮族自治区'],['西藏南部','大峡谷']),
('river-tarim','塔里木河','river',84.3,40.8,'新疆塔里木盆地','中国最长的内流河','塔里木河位于新疆南部，是中国最长的内流河。内流河的水不会直接流入海洋，它滋养着盆地边缘的绿洲。','塔里木河不找海，在盆地里把绿洲灌溉。','塔里木河的水会直接流入海洋吗？','不会，它是内流河',['会，流入东海','会，流入渤海','会，流入南海'],['内流河','新疆南部']),
('plateau-mongolia','内蒙古高原','plateau',112.0,43.4,'中国北部','开阔的草原与高原','内蒙古高原横贯中国北部，地势较为平坦开阔。东部草原广布，向西逐渐可以看到荒漠景观。','北方高原长长一条，东边草原、西边更干燥。','哪座高原横贯中国北部？','内蒙古高原',['云贵高原','青藏高原','黄土高原'],['中国北部','平坦开阔']),
('plateau-loess','黄土高原','plateau',108.0,36.5,'黄河中游一带','千沟万壑的黄色大地','黄土高原分布在黄河中游一带，覆盖着深厚的黄土。流水切出了许多沟壑，保护植被可以帮助减少水土流失。','黄土厚，沟壑多；绿树留住土和水。','哪座高原以深厚黄土和众多沟壑著称？','黄土高原',['内蒙古高原','云贵高原','青藏高原'],['黄河中游','千沟万壑']),
('plateau-yungui','云贵高原','plateau',104.5,25.5,'云南东部与贵州一带','起伏的高原与喀斯特','云贵高原主要位于云南东部和贵州等地。这里地面起伏较大，石灰岩地区可以见到峰林、溶洞等喀斯特景观。','云南贵州找高原，峰林溶洞在身边。','云贵高原的“云”和“贵”主要指哪里？','云南与贵州',['四川与重庆','甘肃与青海','湖南与湖北'],['中国西南部','喀斯特景观']),
('plain-north','华北平原','plain',116.0,36.0,'太行山以东一带','大河塑造的平坦土地','华北平原位于太行山以东，黄河、海河、淮河等河流带来的泥沙参与塑造了这片平原。这里城镇和农田分布广。','太行往东看，平原铺成毯；大河带来土，农田连成片。','华北平原位于太行山的哪一侧？','东侧',['西侧','北侧','山顶上'],['太行山以东','冲积平原']),
('plain-yangtze','长江中下游平原','plain',115.0,30.3,'长江中下游沿岸','河网密布的鱼米之乡','长江中下游平原沿长江两岸分布，地势低平，河流、湖泊众多。温暖湿润的环境适合水稻等作物生长。','跟着长江向东飞，河湖稻田连成堆。','哪片平原以河湖众多、鱼米之乡闻名？','长江中下游平原',['东北平原','塔里木盆地','青藏高原'],['沿长江分布','鱼米之乡']),
('basin-junggar','准噶尔盆地','basin',86.5,45.4,'新疆北部','天山北边的大盆地','准噶尔盆地位于天山以北、阿尔泰山以南。盆地内部有荒漠，边缘有绿洲，和天山南侧的塔里木盆地遥遥相对。','天山上面准噶尔，天山下面塔里木。','准噶尔盆地位于天山的哪一侧？','北侧',['南侧','东侧','西侧'],['新疆北部','天山北侧']),
('basin-qaidam','柴达木盆地','basin',95.0,37.5,'青海省西北部','高原上的“聚宝盆”','柴达木盆地位于青海省西北部，四周高山环绕。这里有盐湖等景观，矿产资源丰富，所以常被称作“聚宝盆”。','青海高原放个盆，盐湖矿产藏其中。','常被称作“聚宝盆”的盆地是？','柴达木盆地',['四川盆地','准噶尔盆地','塔里木盆地'],['青海西北部','盐湖与矿产']),
