 coord=p.get('centroid') or p['center']
 # Regional labels are teaching groupings, not another administrative level.
 places.append(dict(id='province-'+str(p['adcode']),name=short,fullName=name,category='province',adcode=p['adcode'],coord=coord,location=region+' · '+kind,region=region,kind=kind,abbr=abbr,tagline=abbr+' · '+region,description=desc,memory=memory,tags=[kind,'简称：'+abbr],quiz=dict(question=name+'的简称是？',answer=abbr,wrong=[x[1] for x in provinces if x[1]!=abbr][:3],explanation=name+'的简称是“'+abbr+'”。'+desc)))
